// События мира. Проверяются в начале каждой части дня.
// when — условие; chance — вероятность; repeat + cooldown — повторяющиеся; manual — только по эффекту/расписанию.

export const events = {
  ev_intro: {
    when: { day: 1, phase: 'morning' },
    title: 'Утро на улице Изумрудных Фонарей',
    text: 'Солнце добралось до кровати раньше, чем он был к этому готов. С Пассажа Вазари доносился плеск фонтана и первый, ещё сонный оркестрион, на подушке рядом обнаружилась чужая перламутровая шпилька, а в голове — лёгкая, почти вежливая тяжесть вчерашнего вечера.\n\nОбычный день. Можно потренироваться, можно спуститься в «Лютес» за кофе, можно пойти туда, где сегодня говорят что-нибудь интересное.',
    kind: 'intro',
  },

  ev_charlotte_note: {
    when: { day: 1, phase: ['day', 'evening'] },
    title: 'Записка',
    text: 'Мальчишка-разносчик из «Паровой птицы» нашёл его так быстро, будто ему заплатили за скорость отдельно. Записка была сложена вчетверо, почерк угадывался ещё до того, как он её развернул.\n\n«Шевалье! Мне нужно поговорить с вами. Не о вас — о вашей семье. Я в „Лютесе“ и буду ждать до темноты. — Ш.»\n\n«Не о вас» было подчёркнуто дважды. Это задевало сильнее, чем стоило бы.',
    effects: [{ add: 'inv_charlotte' }],
  },

  ev_skate_rumor: {
    when: { all: [{ dayGte: 1 }, { lacks: 'rum_skate' }, { phase: ['morning', 'day'] }] },
    chance: 0.25, repeat: true, cooldown: 8,
    logText: 'На причалах снова говорят о крупном скате у южной стены.',
    effects: [{ add: 'rum_skate' }],
  },

  ev_josie_arrives: {
    when: { dayGte: 2, phase: 'morning' },
    title: 'Три звонка',
    text: 'Паровой лифт звякнул трижды подряд — так звонит только один человек на свете. Жози вошла, не дожидаясь приглашения, бросила перчатки на кресло, из которого невозможно выбраться без посторонней помощи, и объявила, что мать опять пригласила к ужину «очень приличного молодого человека».\n\n«Я поживу у тебя пару дней». Это не было вопросом.',
    effects: [{ place: { who: 'char_josie', loc: 'loc_apartment', for: 12 } }, { relAdd: ['char_josie', 'Сбежала из поместья'] }],
  },

  ev_josie_leaves: {
    manual: false,
    when: { all: [{ fired: 'ev_josie_arrives' }, (s) => !s.whereabouts.char_josie || (s.whereabouts.char_josie.until != null && s.whereabouts.char_josie.until <= ((s.day - 1) * 4 + s.phase))] },
    title: 'Жози уехала',
    text: (s) => 'На столике в гостиной осталась записка: «Мать прислала карету. Не скучай слишком сильно. Ж.»' +
      (s.cards.info_josie_louis
        ? ' И ниже, другим нажимом: «Про склады — я буду слушать. Только не делай глупостей без меня».'
        : (s.flags.nectar_started ? ' И ниже, другим нажимом: «Ты мне так и не сказал, во что ввязался».' : '')),
    effects: [{ relRemove: ['char_josie', 'Сбежала из поместья'] }],
  },
};
